#!/usr/bin/env python3
"""AP3G: finite intrinsic-aspect relation (IAR) membership/gauge/coexistence diagnostic."""
from __future__ import annotations
from itertools import combinations, product
import json
from pathlib import Path

S=('r0','r1','ps','pv','qs','qv')
CP=frozenset(('r0','r1','ps','pv')); CQ=frozenset(('r0','r1','qs','qv'))
# Compatibility is generated by simultaneous membership in CP or CQ.
def compatible(a,b): return a==b or ({a,b} <= CP) or ({a,b} <= CQ)
def is_clique(c): return all(compatible(a,b) for a in c for b in c)
def maximal_proper_contexts():
 allsub=[frozenset(x) for r in range(1,len(S)) for x in combinations(S,r) if is_clique(x)]
 return [c for c in allsub if not any(c < d for d in allsub)]
def vals(context):
 out=[]
 for bits in product((0,1),repeat=len(context)):
  d=dict(zip(sorted(context),bits))
  if 'ps' in d and d['ps']!=d['r0']:continue
  if 'qs' in d and d['qs']!=d['r1']:continue
  out.append(d)
 return out
def key(context,d): return (tuple(sorted(context)),tuple((v,d[v]) for v in sorted(context)))
def main():
 contexts=maximal_proper_contexts()
 valuations={tuple(sorted(c)):vals(c) for c in contexts}
 raw=[]
 for c in contexts:
  for d in vals(c):
   for u in (0,1):raw.append((c,d,u))
 modes={key(c,d) for c,d,u in raw}
 # cross context public-compatible pairs and whole-content amalgamations
 pvals=vals(CP);qvals=vals(CQ);compatible_pairs=[];unique=True
 for p in pvals:
  for q in qvals:
   if p['r0']==q['r0'] and p['r1']==q['r1']:
    whole={**p,**q}
    # common r-values agree by condition, so union is a unique full vocabulary valuation.
    compatible_pairs.append((p,q,whole))
    if len(whole)!=6:unique=False
 nonmax=frozenset(('r0','r1','ps'))
 incompatible=frozenset(('ps','qs'))
 checks={
  'exactly_CP_CQ_are_maximal_proper_contexts':set(contexts)=={CP,CQ},
  'each_context_has_eight_constraint_satisfying_valuations':all(len(vals(c))==8 for c in contexts),
  '32_gauge_labelled_descriptions_quotient_to_16_modes':len(raw)==32 and len(modes)==16,
  'all_modes_have_proper_bounded_contexts':all(len(c)<len(S) for c in contexts),
  'exactly_16_cross_context_public_compatible_pairs':len(compatible_pairs)==16,
  'cross_context_compatible_pairs_have_unique_whole_content_amalgamation':unique,
  'nonmaximal_and_noncompatible_subsets_excluded':nonmax not in contexts and not is_clique(incompatible),
  'phenomenality_not_inferred_from_IAR_structure':True,
 }
 result={
  'scope':'Finite AP3G IAR diagnostic. The self-presentability relation is stipulated as a new formal relation; ground identity and consciousness are not modeled or proven.',
  'vocabulary':list(S),'maximal_proper_contexts':[sorted(c) for c in contexts],
  'valuations_per_context':{str(k):len(v) for k,v in valuations.items()},'gauge_labelled_description_count':len(raw),'IAR_mode_count':len(modes),
  'cross_context_public_compatible_pair_count':len(compatible_pairs),
  'registered_checks':checks,'all_registered_checks_pass':all(checks.values()),
  'conditional_statement':'If the IAR relation is warranted as the genuine-mode membership law and the aware-ground self-presentation/plenitude package is accepted, every one of the 16 gauge-inequivalent IAR modes is conditionally realised as a nonexclusive aspect. This test supplies neither warrant nor phenomenality.',
  'restricted_conclusion':'IAR is an explicit, nontrivial formal candidate for mode membership (domain, gauge quotient, inclusion/exclusion, boundedness, coexistence). Its new compatibility relation requires independent metaphysical or physical justification.'
 }
 Path(__file__).with_name('Point-Sphere_Appearance_Plenitude_Intrinsic_Aspect_Relation_v1.json').write_text(json.dumps(result,indent=2)+'\n')
 print(json.dumps(result,indent=2))
if __name__=='__main__':main()
